function buildBatchQueries(sysRows, netRows, ldiRows) { sysRows = Array.isArray(sysRows) ? sysRows : []; netRows = Array.isArray(netRows) ? netRows : []; ldiRows = Array.isArray(ldiRows) ? ldiRows : [];
    const queries = [];
    if (sysRows.length > 0) { const ph = sysRows.map((_, i) => { const b = i * 11; return `(NOW(),$${b+1},$${b+2},$${b+3},$${b+4},$${b+5},$${b+6},$${b+7},$${b+8},$${b+9},$${b+10},$${b+11})`; }).join(','); const params = []; for (const r of sysRows) { params.push(r.device_id, r.cpu_cores, r.cpu_load_percent, r.ram_total_mb, r.ram_used_mb, r.ram_free_mb, r.disk_total_gb, r.disk_used_gb, r.disk_free_gb, r.disk_description, r.temp_c); } queries.push({ name: 'sys', count: sysRows.length, sql: 'INSERT INTO public.sys_metrics ("time",device_id,cpu_cores,cpu_load_percent,ram_total_mb,ram_used_mb,ram_free_mb,disk_total_gb,disk_used_gb,disk_free_gb,disk_description,temp_c) VALUES ' + ph, params: params }); }
    if (netRows.length > 0) { const ph = netRows.map((_, i) => { const b = i * 9; return `(NOW(),$${b+1},$${b+2},$${b+3},$${b+4},$${b+5},$${b+6},$${b+7},$${b+8},$${b+9})`; }).join(','); const params = []; for (const r of netRows) { params.push(r.device_id, r.iface_name, r.rx_mbps, r.tx_mbps, r.rx_errors, r.tx_errors, r.rx_drops, r.tx_drops, r.status); } queries.push({ name: 'net', count: netRows.length, sql: 'INSERT INTO public.net_metrics ("time",device_id,iface_name,rx_mbps,tx_mbps,rx_errors,tx_errors,rx_drops,tx_drops,status) VALUES ' + ph, params: params }); }
    if (ldiRows.length > 0) { const ph = ldiRows.map((_, i) => { const b = i * 8; return `(NOW(),$${b+1},$${b+2},$${b+3},$${b+4},$${b+5},$${b+6},$${b+7},$${b+8})`; }).join(','); const params = []; for (const r of ldiRows) { params.push(r.device_id, r.throughput, r.temperature, r.humidity, r.power_watt, r.vibration, r.pe_1, r.je_1); } queries.push({ name: 'ldi', count: ldiRows.length, sql: 'INSERT INTO public.ldi_metrics ("time",device_id,throughput,temperature,humidity,power_watt,vibration,pe_1,je_1) VALUES ' + ph, params: params }); }
    return queries;
}

