    msg.payload = { error: 'Payload must be a JSON array' };
    return msg;
}

msg._ldiBatch = [];
const num = v => (v === 0) ? 0 : (Number(v) || null);
const int = v => (v === 0) ? 0 : (parseInt(v) || null);
for (const item of msg.payload) {
    if (!item || !item.eqp_id) continue;
    msg._ldiBatch.push({
        eqp_id: String(item.eqp_id),
        factory: String(item.factory || ''),
        process: String(item.process || ''),
        mo: String(item.mo || ''),
        fpn: String(item.fpn || ''),
        layer_name: String(item.layer_name || ''),
        resist_dosage: num(item.resist_dosage),
        scale_x: num(item.scale_x),
        scale_y: num(item.scale_y),
        temperature: num(item.temperature),
        humidity: num(item.humidity),
        scan_speed: num(item.scan_speed),
        air_vacuum: num(item.air_vacuum),
        thickness: num(item.thickness),
        board_no: int(item.board_no),
        total_board: int(item.total_board),
        total_time: num(item.total_time),
        filmno: String(item.filmno || ''),
        board_id: String(item.board_id || ''),
        resist: item.resist ? String(item.resist) : null,
        state: item.state !== false,
        scale_mode: String(item.scale_mode || ''),
        pe_1: num(item.pe_1),
        pe_2: num(item.pe_2),
        pe_3: num(item.pe_3),
        pe_4: num(item.pe_4),
        pe_5: num(item.pe_5),
        pe_6: num(item.pe_6),
        je_1: num(item.je_1),
        je_2: num(item.je_2),
        je_3: num(item.je_3),
        je_4: num(item.je_4),
        pe_setting: num(item.pe_setting),
        je_setting: num(item.je_setting),
        log_id: String(item.log_id || '')
    });
}


if (msg._ldiBatch.length === 0) {
    msg.statusCode = 200;
    msg.payload = { message: 'Empty batch' };
    return msg;
}

const cols = [
    'factory', 'process', 'eqp_id', 'mo', 'fpn', 'layer_name', 'resist_dosage', 'scale_x', 'scale_y', 
    'temperature', 'humidity', 'scan_speed', 'air_vacuum', 'thickness', 'board_no', 'total_board', 
    'total_time', 'filmno', 'board_id', 'resist', 'state', 'scale_mode', 
    'pe_1', 'pe_2', 'pe_3', 'pe_4', 'pe_5', 'pe_6', 
    'je_1', 'je_2', 'je_3', 'je_4', 'pe_setting', 'je_setting', 'log_id'
];

let params = [];
const placeholders = msg._ldiBatch.map((row, i) => {
    const b = i * cols.length;
    cols.forEach(col => params.push(row[col]));
    const p = cols.map((_, j) => `$${b + j + 1}`).join(',');
    return `(NOW(), ${p})`;
}).join(',');

msg.query = `INSERT INTO public.ldi_data ("time", ${cols.join(',')}) VALUES ${placeholders} ON CONFLICT (log_id, "time") DO NOTHING;`;
msg.params = params;


const pool = global.get('pgPool');
if (pool) {
    pool.query(msg.query, msg.params, (err) => {
        if (err) {
            node.error('LDI INSERT failed: ' + err.message);
            // Auto-recovery watchdog for a specific, live-verified failure mode:
